]

const CELL_ROWS = 4

export type OctCell = { char: string; color?: string; background?: string }

function hex(key: string): string | undefined {
  return key === ' ' ? undefined : `#${PALETTE[key]!.toString(16).padStart(6, '0')}`
}

// 1 マス（8 ドット）を、文字 1 つ・文字色・地色にする。端末は 1 マス 2 色までで、透明（端末の既定色）も 1 色に数える。
// 決め方は元の HTML の encodeOctantCell と同じ: 地色は透明があれば透明、無ければ最初のドットの色。もう 1 色が文字の色。
// 絵（octant_art.ts）はどのマスも 2 色以内で、3 色目は来ない（テストで全コマ確かめている）
function encode(pixels: readonly string[]): OctCell {
  const colors = [...new Set(pixels)]
  const back = colors.includes(' ') ? ' ' : colors[0]!
  const front = colors.find(color => color !== back) ?? back
  const bits = front === back ? 0 : pixels.reduce((sum, dot, k) => (dot === front ? sum | (1 << k) : sum), 0)

  return { char: String.fromCodePoint(GLYPHS[bits]!), color: hex(front), background: hex(back) }
}

// 20×12 ドットの絵を、10 文字 × 3 行のマスにする
export function octCells(rows: readonly string[]): OctCell[][] {
  const width = rows[0]!.length
  const out: OctCell[][] = []

  for (let y = 0; y < rows.length; y += CELL_ROWS) {
    const line: OctCell[] = []

    for (let x = 0; x < width; x += 2) {
      const pixels: string[] = []

      for (let dy = 0; dy < CELL_ROWS; dy++) {
        pixels.push(rows[y + dy]?.[x] ?? ' ', rows[y + dy]?.[x + 1] ?? ' ')
      }

      line.push(encode(pixels))
    }

    out.push(line)
  }

  return out
}

